-- Biology Ch1 (The Cell) — Batch 3 of 4: Prokaryotes (structure, classification, growth) (AAMC 2A "Prokaryotes and Viruses (BIO)")
-- 25 questions, all confidence >=4 (cited to OpenStax Microbiology (prokaryote structure/wall/Gram/growth) + Biology 2e (domains)).
-- Difficulty 7 easy / 10 medium / 8 hard (every hard passes the two-axis Hard-Tier gate); answer key A/B/C/D = 7/6/6/6; deduped internally + vs the live Batch 1+2+2.
-- section bio_biochem, discipline biology, foundation 2A. Re-runnable: subtopic-scoped DELETE. Run in the Supabase SQL editor.
BEGIN;
DELETE FROM questions WHERE topic = 'The Cell' AND subtopic IN ('Bacterial Growth Curve', 'Bacterial Shapes', 'Cell Theory & Prokaryotic Fundamentals', 'Prokaryotic Cell Wall & Gram Staining', 'Prokaryotic Domains: Archaea and Bacteria', 'Prokaryotic Flagella & Motility', 'Prokaryotic Growth & Metabolism');

-- Q1 [Bacterial Growth Curve · easy · Skill 1 · ans C] (g73)
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES (
    'bio_biochem', 'The Cell', 'Bacterial Growth Curve',
    $qt73$A frozen E. coli stock is thawed and inoculated into a flask of fresh broth. For roughly the first hour the total cell number barely changes, yet the cells enlarge and begin synthesizing ribosomes and the enzymes needed to use the new medium. This culture is most likely in which growth phase?$qt73$,
    $op73$[{"label":"A","text":"Log (exponential) phase, because the cells have begun dividing by binary fission at their maximal rate"},{"label":"B","text":"Stationary phase, because the rate of cell division equals the rate of cell death"},{"label":"C","text":"Lag phase, because the cells are metabolically active and gearing up to grow but are not yet increasing in number"},{"label":"D","text":"Death (decline) phase, because accumulated waste and exhausted nutrients are killing cells faster than they divide"}]$op73$::jsonb,
    'C',
    $ex73$This is a Biology question that falls under the content category 'Prokaryotes and Viruses (BIO)'. The answer is C because the hallmark of the lag phase is metabolic activity and preparation for growth (synthesizing proteins and ribosomes, enlarging) while cell number stays essentially flat. When an inoculum is added to fresh medium, the initial phase is the lag phase: the number of cells does not change, yet cells "grow larger and are metabolically active, synthesizing proteins needed to grow within the medium" and repairing any damage from the transfer (Microbiology, lines 14664-14668). Only after this adaptation period do the cells enter the log phase and begin dividing exponentially. The scenario describes exactly this gearing-up with little to no division, which uniquely identifies the lag phase. (Choice A) Log phase is when "the cells are actively dividing by binary fission and their number increases exponentially" (lines 14672-14673); here cell number is barely changing, so the culture is not yet in log phase. (Choice B) In stationary phase "the number of new cells created by cell division is now equivalent to the number of cells dying" after the population has already grown to a plateau (lines 14696-14698); this requires a large, division-balanced population, not a freshly inoculated one. (Choice C) Correct: the cells are metabolically active and preparing to grow while cell number does not change, the defining features of the lag phase (lines 14665-14667). (Choice D) Death phase occurs when "a culture medium accumulates toxic waste and nutrients are exhausted" so that "the number of dying cells exceeds the number of dividing cells" (lines 14713-14714); a flask of fresh broth just inoculated has neither exhausted nutrients nor accumulated waste. This is a Knowledge of Scientific Concepts and Principles question because you must recall the defining metabolic and cell-number features of each bacterial growth phase and match them to the lag phase.$ex73$,
    'easy', '2B', $cc73$Prokaryotes and Viruses (BIO)$cc73$, 'biology', 1, 75
  ) RETURNING id
)
INSERT INTO question_distractor_metadata (question_id, choice_label, distractor_category, archetype)
SELECT id, 'A', 'adjacent_fact', $a73A$Names the very next phase (log/exponential) and its true defining feature, attractive to a student who skips the 'no division yet' clue$a73A$ FROM q
UNION ALL SELECT id, 'B', 'misconception', $a73B$Confuses lag (no division yet) with stationary (division balanced by death), both of which show flat cell number on a curve$a73B$ FROM q
UNION ALL SELECT id, 'D', 'reversed_relationship', $a73D$Applies end-of-culture conditions (waste/nutrient exhaustion) to a freshly inoculated culture, reversing the timeline$a73D$ FROM q;

-- Q2 [Bacterial Growth Curve · medium · Skill 2 · ans D] (g74)
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES (
    'bio_biochem', 'The Cell', 'Bacterial Growth Curve',
    $qt74$A sealed flask of Staphylococcus aureus is followed over time, and its total viable count climbs, then settles into a stable plateau. A technician confirms that individual cells in the plateaued culture are still dividing by binary fission. Which condition most directly accounts for why the viable count holds steady even though division continues?$qt74$,
    $op74$[{"label":"A","text":"Nutrients and oxygen remain plentiful, so cells continue to enlarge but pause division until the next round of replication is triggered."},{"label":"B","text":"Toxic wastes have accumulated to a level that causes the number of dying cells to exceed the number being produced, so the count is poised to fall."},{"label":"C","text":"The culture has entered exponential growth, in which the rate of division is constant and the population number increases logarithmically over time."},{"label":"D","text":"As nutrients are depleted and wastes accumulate, the rate at which new cells are produced by division has come to equal the rate at which cells die."}]$op74$::jsonb,
    'D',
    $ex74$This is a Biology question that falls under the content category 'Prokaryotes and Viruses (BIO)'. The answer is D because a stable plateau in viable count, with division still occurring, is the defining signature of the stationary phase, in which the birth rate has fallen to match the death rate. As nutrients are gradually used up, wastes accumulate, and oxygen is depleted in the closed flask, population growth stalls and "the total number of live cells reaches a plateau referred to as the stationary phase" (lines 14693-14696). The text states explicitly that in this phase "the number of new cells created by cell division is now equivalent to the number of cells dying; thus, the total population of living cells is relatively stagnant" (lines 14697-14698), so continued division does not raise the count because death cancels it. The flat line is therefore a dynamic balance, not a halt in division. (Choice A) The closed flask is running down its nutrients and oxygen, not holding them plentiful, and the text attributes the plateau to "gradual depletion of oxygen" and nutrients (lines 14694-14695), so a plentiful-resource, paused-division picture contradicts the cause of the plateau. (Choice B) Wastes do accumulate, but a death rate that exceeds the birth rate describes the death phase, where "the number of dying cells exceeds the number of dividing cells, leading to an exponential decrease in the number of cells" (lines 14713-14714); during a stable plateau the rates are equal, not unequal. (Choice C) In the logarithmic (exponential) phase "the cells are actively dividing by binary fission and their number increases exponentially" (lines 14672-14673), which produces a rising count, not the steady plateau described. (Choice D) Correct: equal rates of division and death hold the live count constant despite ongoing binary fission, matching "the number of new cells created by cell division is now equivalent to the number of cells dying" (lines 14697-14698). This is a Scientific Reasoning and Problem Solving question because you must infer, from the observation of a steady count alongside ongoing division, which balance of birth and death rates the closed-culture conditions have produced.$ex74$,
    'medium', '2B', $cc74$Prokaryotes and Viruses (BIO)$cc74$, 'biology', 2, 105
  ) RETURNING id
)
INSERT INTO question_distractor_metadata (question_id, choice_label, distractor_category, archetype)
SELECT id, 'A', 'misconception', $a74A$Assumes a plateau means resources are abundant and division is merely paused, ignoring that a closed flask depletes nutrients and oxygen$a74A$ FROM q
UNION ALL SELECT id, 'B', 'adjacent_fact', $a74B$States the death-phase condition (death rate exceeds birth rate) instead of the stationary-phase balance$a74B$ FROM q
UNION ALL SELECT id, 'C', 'process_step_confusion', $a74C$Confuses the log/exponential phase (rising count) with the stationary phase (flat count)$a74C$ FROM q;

-- Q3 [Bacterial Growth Curve · hard · Skill 4 · ans A] (g75)
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES (
    'bio_biochem', 'The Cell', 'Bacterial Growth Curve',
    $qt75$A bacteriologist grows a Pseudomonas culture in a sealed broth tube and records the viable count (CFU/mL) at successive timepoints, shown below. She plans to add a beta-lactam-type drug that kills a bacterium ONLY while that cell is actively building new cell wall during division. \( \begin{array}{cc} \text{Time (h)} & \text{Viable count (CFU/mL)} \\ 0 & 1.0\times10^{4} \\ 2 & 1.0\times10^{4} \\ 4 & 4.0\times10^{4} \\ 6 & 1.6\times10^{5} \\ 8 & 6.4\times10^{5} \end{array} \) If she wants the drug to kill the largest fraction of the population, when should she add it relative to the culture's current state?$qt75$,
    $op75$[{"label":"A","text":"Now, because the count is still climbing exponentially, indicating a log (exponential) phase culture whose cells are actively dividing and building cell wall."},{"label":"B","text":"After waiting for the count to plateau, because a stationary-phase culture holds the greatest number of live cells for the drug to attack at once."},{"label":"C","text":"During the earlier interval when the count held steady, because lag-phase cells are enlarging and gearing up, making their walls easiest to breach."},{"label":"D","text":"It makes no difference when she adds it, because a drug targeting cell-wall synthesis kills cells at the same rate in every growth phase."}]$op75$::jsonb,
    'A',
    $ex75$This is a Biology question that falls under the content category 'Prokaryotes and Viruses (BIO)'. The answer is A because the viable count quadruples over each 2-hour interval from hour 4 onward (4.0×10^4 → 1.6×10^5 → 6.4×10^5), an exponential climb that identifies the culture as currently in the log (exponential) phase, when cells are dividing fastest and a drug that kills only dividing cells does the most damage. In the log phase "the cells are actively dividing by binary fission and their number increases exponentially," and the text notes the log phase "is also the stage where bacteria are the most susceptible to the action of disinfectants and common antibiotics that affect protein, DNA, and cell-wall synthesis." A beta-lactam blocks cell-wall (peptidoglycan) synthesis, so it can only harm a cell that is actively building new wall to divide; the maximum proportion of such cells exists during exponential growth, which the latest timepoints show is happening now. Waiting changes the phase to one with fewer dividing cells, reducing the drug's effect. (Choice A) Correct: the steady exponential rise at the final timepoints marks an actively dividing log-phase culture, the phase of greatest susceptibility to a cell-wall-synthesis inhibitor. (Choice B) Tempting partial truth: a stationary-phase plateau does hold many live cells, but in stationary phase "the synthesis of peptidoglycans, proteins, and nucleic-acids" slows, so "stationary cultures are less susceptible to antibiotics that disrupt these processes" — cells that are not building wall are not killed by a beta-lactam, so total cell number is irrelevant. (Choice C) The flat count from hour 0 to 2 is the lag phase, when "the number of cells does not change" because cells are gearing up but not yet dividing; non-dividing cells are not building new wall, so a beta-lactam is least, not most, effective then. (Choice D) Reversed/false: the drug's lethality is phase-dependent precisely because it requires active cell-wall synthesis; phases differ greatly in the fraction of dividing cells, so the kill rate is not uniform across phases. This is a Data-based and Statistical Reasoning question because you must read the viable-count-versus-time values, recognize the exponential (fixed-fold-per-interval) pattern as the log phase, and link that data-derived phase to the drug's mechanism to predict the optimal timing.$ex75$,
    'hard', '2B', $cc75$Prokaryotes and Viruses (BIO)$cc75$, 'biology', 4, 150
  ) RETURNING id
)
INSERT INTO question_distractor_metadata (question_id, choice_label, distractor_category, archetype)
SELECT id, 'B', 'partial_truth', $a75B$Stationary-phase plateau holds the most live cells, so it must be the best target — ignores that non-dividing stationary cells are not building wall and are less susceptible to a beta-lactam$a75B$ FROM q
UNION ALL SELECT id, 'C', 'process_step_confusion', $a75C$Confuses lag-phase metabolic 'gearing up' and cell enlargement with active division, treating the flat early count as the most vulnerable phase$a75C$ FROM q
UNION ALL SELECT id, 'D', 'reversed_relationship', $a75D$Asserts phase-independent killing, denying that a cell-wall-synthesis inhibitor's lethality depends on the fraction of actively dividing cells$a75D$ FROM q;

-- Q4 [Bacterial Shapes · easy · Skill 1 · ans A] (g59)
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES (
    'bio_biochem', 'The Cell', 'Bacterial Shapes',
    $qt59$A microbiology student examines a stained smear from a patient with strep throat and observes round, spherical bacterial cells. Which morphology term names this spherical cell shape?$qt59$,
    $op59$[{"label":"A","text":"Coccus"},{"label":"B","text":"Bacillus"},{"label":"C","text":"Spirillum"},{"label":"D","text":"Vibrio"}]$op59$::jsonb,
    'A',
    $ex59$This is a Biology question that falls under the content category 'Prokaryotes and Viruses (BIO)'. The answer is A because a coccus is the morphology term for a spherical bacterial cell, which matches the round cells seen in a strep throat smear (the genus Streptococcus is composed of cocci). OpenStax Microbiology lists the standard prokaryotic shapes directly: "Common shapes include spherical (coccus), rod-shaped (bacillus), or curved (spirillum, spirochete, or vibrio)." The student sees round, spherical cells, so the correct paired term is coccus. The other listed terms each name a real but different morphology: bacillus is reserved for rod-shaped cells, while spirillum and vibrio are curved forms, none of which describe a sphere. (Choice A) Correct. The text pairs "spherical" with "(coccus)," so the round cells of a strep throat smear are cocci. (Choice B) Bacillus is the term for "rod-shaped" cells, not spherical ones, so it describes an elongated rather than round morphology. (Choice C) Spirillum is one of the "curved" forms (a rigid spiral), not a sphere. (Choice D) Vibrio is also a "curved" form (a short comma-shaped cell), not a spherical one. This is a Knowledge of Scientific Concepts and Principles question because you must recall the standard prokaryotic morphology vocabulary and match the term coccus to a spherical cell shape.$ex59$,
    'easy', '2B', $cc59$Prokaryotes and Viruses (BIO)$cc59$, 'biology', 1, 70
  ) RETURNING id
)
INSERT INTO question_distractor_metadata (question_id, choice_label, distractor_category, archetype)
SELECT id, 'B', 'adjacent_fact', $a59B$Names the correct vocabulary system but substitutes the rod-shape term (bacillus) for the sphere term$a59B$ FROM q
UNION ALL SELECT id, 'C', 'adjacent_fact', $a59C$Substitutes a curved/spiral morphology term (spirillum) for the spherical term$a59C$ FROM q
UNION ALL SELECT id, 'D', 'adjacent_fact', $a59D$Substitutes a curved comma-shaped morphology term (vibrio) for the spherical term$a59D$ FROM q;

-- Q5 [Bacterial Shapes · medium · Skill 2 · ans B] (g60)
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES (
    'bio_biochem', 'The Cell', 'Bacterial Shapes',
    $qt60$A technician examining a Gram-stained smear focuses on one isolated cell that is several times longer than it is wide, with two straight, parallel long sides and squared-off, blunt ends, and shows no curvature anywhere along its length. Reasoning only from this described geometry, the technician should classify the cell's morphology as:$qt60$,
    $op60$[{"label":"A","text":"coccus, a roughly spherical cell whose width and length are about equal"},{"label":"B","text":"bacillus, a rod-shaped cell that is elongated with straight sides and squared ends"},{"label":"C","text":"vibrio, a short cell bent into a single comma-like curve"},{"label":"D","text":"coccobacillus, a very short oval cell intermediate between a sphere and a rod"}]$op60$::jsonb,
    'B',
    $ex60$This is a Biology question that falls under the content category 'Prokaryotes and Viruses (BIO)'. The answer is B because a cell that is several times longer than it is wide, with straight parallel sides and squared-off ends and no curvature, matches the rod-shaped morphology named bacillus. The text states that "Bacteria are often described in terms of their general shape. Common shapes include spherical (coccus), rod-shaped (bacillus), or curved (spirillum, spirochete, or vibrio)" (openstax-microbiology.txt, lines 1635-1636). The described geometry has two diagnostic features that pin down the classification: elongation (length much greater than width) rules out the spherical class, and the absence of curvature with straight parallel sides rules out the curved class, leaving the straight rod (bacillus). Mapping the observed dimensions and curvature to the vocabulary, rather than recalling a species name, is the required reasoning step. (Choice A) Coccus is incorrect because a coccus is "spherical," with width and length about equal; a cell several times longer than it is wide is not spherical (lines 1635-1636). (Choice B) Bacillus is correct because it is the "rod-shaped" category, and a rod is precisely an elongated cell with straight parallel sides and squared ends (lines 1635-1636). (Choice C) Vibrio is incorrect because it belongs to the "curved" group (spirillum, spirochete, or vibrio); the described cell explicitly shows no curvature, so a comma-shaped curved cell does not fit (lines 1635-1636). (Choice D) Coccobacillus is incorrect because, as the figure notes, "coccobacillus is a combination of spherical (coccus) and rod-shaped (bacillus)" (line 1641) — a short oval form, not a cell several times longer than it is wide. This is a Scientific Reasoning and Problem Solving question because you must apply morphology vocabulary to a set of described geometric features and infer the correct classification rather than recall a named organism.$ex60$,
    'medium', '2B', $cc60$Prokaryotes and Viruses (BIO)$cc60$, 'biology', 2, 100
  ) RETURNING id
)
INSERT INTO question_distractor_metadata (question_id, choice_label, distractor_category, archetype)
SELECT id, 'A', 'misconception', $a60A$Ignores the stated elongation and defaults to the spherical coccus shape$a60A$ FROM q
UNION ALL SELECT id, 'C', 'adjacent_fact', $a60C$Names a real curved morphology from the same list while overlooking that the cell has no curvature$a60C$ FROM q
UNION ALL SELECT id, 'D', 'partial_truth', $a60D$Picks the intermediate coccus/bacillus blend, capturing rod character but contradicting the several-times-longer dimensions$a60D$ FROM q;

-- Q6 [Cell Theory & Prokaryotic Fundamentals · easy · Skill 1 · ans A] (g51)
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES (
    'bio_biochem', 'The Cell', 'Cell Theory & Prokaryotic Fundamentals',
    $qt51$A student re-runs a classic sealed-broth experiment: nutrient broth is boiled to sterilize it and then sealed, and the sealed flask shows no microbial growth for weeks until the student deliberately introduces a small sample of living bacteria, after which the broth rapidly becomes cloudy with microbes. The student asks which tenet of modern cell theory this result most directly supports.$qt51$,
    $op51$[{"label":"A","text":"All cells arise only from other, pre-existing cells (the principle of biogenesis)."},{"label":"B","text":"The cell is the fundamental structural and functional unit of every living organism."},{"label":"C","text":"All living organisms are composed of one or more cells."},{"label":"D","text":"All cells share a similar chemical composition and a common set of metabolic processes."}]$op51$::jsonb,
    'A',
    $ex51$This is a Biology question that falls under the content category 'Prokaryotes and Viruses (BIO)'. The answer is A because the only way microbes appeared was after living cells were added, demonstrating that the new cells came from pre-existing cells rather than arising spontaneously. The OpenStax Microbiology text states that modern cell theory has two basic tenets, the first being that "All cells only come from other cells (the principle of biogenesis)" (openstax-microbiology.txt, lines 3966-3969). The sterilized, sealed broth stayed lifeless because no living cells were present, and growth occurred only once the student supplied existing bacteria as a source — exactly the result that experiments like Pasteur's used to disprove spontaneous generation, captured in the phrase "Omne vivum ex vivo" ("Life only comes from life") (lines 3919-3924). The observation speaks to the origin of new cells, not to their structural role, their distribution among organisms, or their chemistry. (Choice A) Correct: the appearance of cells only after living cells were introduced directly demonstrates biogenesis — new cells come from pre-existing cells. (Choice B) The text lists "Cells are the fundamental units of organisms" as the second tenet (line 3969), but this experiment says nothing about cells being the basic structural/functional unit; it concerns where new cells come from, so it is a partial truth about cell theory that the data do not test. (Choice C) That all organisms are made of cells is a genuine component of cell theory, yet this result does not address how organisms are built — it addresses the source of new microbes, making this an adjacent fact rather than the supported tenet. (Choice D) Shared chemical composition and common metabolism is a real generalization about cells, but the experiment manipulates the presence of living cells, not chemistry, so this observation provides no evidence for it. This is a Knowledge of Scientific Concepts and Principles question because you must recall the tenets of modern cell theory and match the principle of biogenesis to an observation that cells appear only when pre-existing cells are present.$ex51$,
    'easy', '2B', $cc51$Prokaryotes and Viruses (BIO)$cc51$, 'biology', 1, 75
  ) RETURNING id
)
INSERT INTO question_distractor_metadata (question_id, choice_label, distractor_category, archetype)
SELECT id, 'B', 'partial_truth', $a51B$Other real cell-theory tenet (fundamental unit) that the data do not test$a51B$ FROM q
UNION ALL SELECT id, 'C', 'adjacent_fact', $a51C$Classic cell-theory statement (organisms made of cells) unrelated to the origin observation$a51C$ FROM q
UNION ALL SELECT id, 'D', 'misconception', $a51D$Plausible-sounding 'shared chemistry' generalization not part of the tested tenet$a51D$ FROM q;

-- Q7 [Cell Theory & Prokaryotic Fundamentals · easy · Skill 1 · ans B] (g52)
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES (
    'bio_biochem', 'The Cell', 'Cell Theory & Prokaryotic Fundamentals',
    $qt52$A microscopist examines a bacterial cell and finds its single circular chromosome concentrated in an irregularly shaped region of the cytoplasm that has no surrounding membrane. What is this DNA-containing region called?$qt52$,
    $op52$[{"label":"A","text":"The nucleus, the membrane-enclosed compartment that houses the cell's chromosomes"},{"label":"B","text":"The nucleoid, the membrane-free region of the cytoplasm where the chromosomal DNA is localized"},{"label":"C","text":"A plasmid, a small extrachromosomal DNA molecule that replicates independently of the main chromosome"},{"label":"D","text":"The capsule, the polysaccharide layer outside the cell wall that helps the cell attach to surfaces"}]$op52$::jsonb,
    'B',
    $ex52$This is a Biology question that falls under the content category 'Prokaryotes and Viruses (BIO)'. The answer is B because in a prokaryote the chromosomal DNA is not enclosed by a membrane; it is concentrated in a region of the cytoplasm called the nucleoid. OpenStax Biology 2e states that "Prokaryotic DNA is in the cell's central part: the nucleoid," and that all prokaryotes "have chromosomal DNA localized in a nucleoid" (lines 5217-5224). This membrane-free organization is the defining structural difference from eukaryotes, which sequester their DNA inside a true membrane-bound nucleus; OpenStax describes prokaryotes as cells that "lack membrane-enclosed nuclei and organelles" (line 1864). The microscopist's two observations — chromosomal DNA plus the absence of a surrounding membrane — together identify the nucleoid. (Choice A) The nucleus is the membrane-enclosed compartment of eukaryotes; the explicit observation of "no surrounding membrane" rules it out, since prokaryotes by definition lack a true nucleus. (Choice B) Correct: the nucleoid is the non-membrane-bound region holding the prokaryotic chromosome. (Choice C) A plasmid is a small extrachromosomal DNA molecule, not the cell's single main chromosome, so it does not name the region holding the chromosomal DNA. (Choice D) The capsule is an external polysaccharide layer outside the cell wall used for attachment, not a DNA-containing region; "The capsule enables the cell to attach to surfaces" (line 5227). This is a Knowledge of Scientific Concepts and Principles question because you must recall that prokaryotes house their chromosomal DNA in a membrane-free nucleoid rather than in a true nucleus.$ex52$,
    'easy', '2B', $cc52$Prokaryotes and Viruses (BIO)$cc52$, 'biology', 1, 75
  ) RETURNING id
)
INSERT INTO question_distractor_metadata (question_id, choice_label, distractor_category, archetype)
SELECT id, 'A', 'misconception', $a52A$Confusing the prokaryotic nucleoid with a true membrane-bound nucleus$a52A$ FROM q
UNION ALL SELECT id, 'C', 'adjacent_fact', $a52C$Naming a real prokaryotic DNA element (plasmid) that is extrachromosomal rather than the main chromosome region$a52C$ FROM q
UNION ALL SELECT id, 'D', 'adjacent_fact', $a52D$Naming a real external prokaryotic structure (capsule) that contains no DNA$a52D$ FROM q;

-- Q8 [Cell Theory & Prokaryotic Fundamentals · medium · Skill 2 · ans C] (g53)
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES (
    'bio_biochem', 'The Cell', 'Cell Theory & Prokaryotic Fundamentals',
    $qt53$A researcher characterizes an unknown cell and records three features: it has no membrane-bound organelles, its DNA is a single circular chromosome lying free in the cytoplasm, and its ribosomes sediment at 70S. Based on this combination of features, the cell must belong to which group?$qt53$,
    $op53$[{"label":"A","text":"The domain Eukarya, because a single circular chromosome and 70S ribosomes are the defining features of eukaryotic cells"},{"label":"B","text":"A fungus, because fungal cells lack membrane-bound organelles and therefore keep their DNA free in the cytoplasm"},{"label":"C","text":"The domain Bacteria or the domain Archaea, because these prokaryotic features rule out the only domain whose cells enclose DNA in a nucleus and carry 80S cytoplasmic ribosomes"},{"label":"D","text":"A protist, because protists are the single-celled organisms that retain 70S ribosomes while losing their membrane-bound organelles"}]$op53$::jsonb,
    'C',
    $ex53$This is a Biology question that falls under the content category 'Prokaryotes and Viruses (BIO)'. The answer is C because the three recorded features are jointly the diagnostic signature of a prokaryote, and the only two prokaryotic domains are Bacteria and Archaea. The text states that "Prokaryotic cells lack a nucleus surrounded by a complex nuclear membrane and generally have a single, circular chromosome located in a nucleoid," while "Eukaryotic cells have a nucleus... that contains multiple, rod-shaped chromosomes" (openstax-microbiology.txt, lines 4328-4331). It further specifies that "Prokaryotic microorganisms are classified within the domains Archaea and Bacteria, whereas eukaryotic organisms are classified within the domain Eukarya" (lines 4341-4342). The ribosome data seal the inference: "Prokaryotic ribosomes... are called 70S ribosomes... whereas eukaryotic cytoplasmic ribosomes have a size of 80S" (lines 4470-4471). A 70S cytoplasmic ribosome plus a naked circular chromosome plus the absence of membrane-bound organelles excludes Eukarya, leaving only the two prokaryotic domains, and nothing in the feature list distinguishes Bacteria from Archaea, so the cell must be one or the other. (Choice A) Eukarya is incorrect and is the central error the item targets: eukaryotic cells are defined by a nucleus, multiple rod-shaped chromosomes, and 80S cytoplasmic ribosomes (lines 5021-5027), the opposite of every feature listed. (Choice B) A fungus is a eukaryote and possesses membrane-bound organelles and a nucleus; it does not keep its DNA free in the cytoplasm, so it cannot match the feature list. (Choice C) Bacteria or Archaea is correct because both are prokaryotic ("Bacteria and Archaea are prokaryotes," openstax-biology-2e.txt, lines 1851-1852) and share the listed features, and the data do not separate the two. (Choice D) A protist is a eukaryote within domain Eukarya; its cytoplasmic ribosomes are 80S and it has membrane-bound organelles and a nucleus, so it is excluded. This is a Scientific Reasoning and Problem Solving question because you must integrate three separate cell features and apply the prokaryote-versus-eukaryote contrast to deduce the domain-level classification of an unknown cell.$ex53$,
    'medium', '2B', $cc53$Prokaryotes and Viruses (BIO)$cc53$, 'biology', 2, 105
  ) RETURNING id
)
INSERT INTO question_distractor_metadata (question_id, choice_label, distractor_category, archetype)
SELECT id, 'A', 'misconception', $a53A$Treating the prokaryotic signature (circular chromosome, 70S) as eukaryotic; mislabeling Eukarya as prokaryotic$a53A$ FROM q
UNION ALL SELECT id, 'B', 'adjacent_fact', $a53B$Naming a real eukaryotic group (fungi) and falsely attributing prokaryotic organization to it$a53B$ FROM q
UNION ALL SELECT id, 'D', 'partial_truth', $a53D$Picking a single-celled eukaryote (protist) on the lure that 'single-celled' equals prokaryotic, ignoring its 80S ribosomes and organelles$a53D$ FROM q;

-- Q9 [Cell Theory & Prokaryotic Fundamentals · medium · Skill 2 · ans D] (g54)
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES (
    'bio_biochem', 'The Cell', 'Cell Theory & Prokaryotic Fundamentals',
    $qt54$A mitotic-spindle inhibitor that prevents the formation of microtubule spindle fibers is added to an actively replicating culture of \(\textit{Escherichia coli}\). Cell counts continue to double on schedule, indicating that bacterial cell division proceeds essentially unaffected. Which feature of \(\textit{E. coli}\) division most directly explains why the drug fails to halt it?$qt54$,
    $op54$[{"label":"A","text":"The bacterial chromosome is sequestered inside a membrane-bound nucleus, so the spindle inhibitor cannot reach the DNA it would otherwise pull apart during division."},{"label":"B","text":"The bacterial division apparatus pulls the duplicated chromosomes to opposite ends using a spindle built from actin filaments rather than tubulin, so the tubulin-targeting drug misses its target."},{"label":"C","text":"The drug halts the cells only briefly; the bacteria pause until the inhibitor is metabolized and then resume spindle-driven division on schedule."},{"label":"D","text":"\\(\\textit{E. coli}\\) divides by binary fission, partitioning its replicated chromosome and constricting the cell with an FtsZ ring rather than a microtubule spindle, so there is no spindle for the drug to disrupt."}]$op54$::jsonb,
    'D',
    $ex54$This is a Biology question that falls under the content category 'Prokaryotes and Viruses (BIO)'. The answer is D because bacteria reproduce by binary fission—a mechanism that does not use a microtubule mitotic spindle—so a drug that blocks spindle formation has no target to act on. In binary fission, the circular chromosome replicates from its origin and the copies are partitioned as the cell elongates; division is then driven by FtsZ, which "assembles into a Z ring on the cytoplasmic membrane" that "defines the division plane" and constricts the cell into two daughter cells (Microbiology, lines 14551-14559). This contractile-ring mechanism is fundamentally different from eukaryotic mitosis, in which a spindle of tubulin microtubules pulls sister chromatids apart; the text notes that "mitosis is a much more complex cellular process than binary fission" (Microbiology, lines 14559-14161). A spindle poison therefore cannot block a process that never builds a spindle in the first place. (Choice A) is wrong because prokaryotes lack a membrane-bound nucleus—"Prokaryotic DNA is in the cell's central part: the nucleoid" (Biology 2e, lines 5217-5218)—and, more importantly, the spindle inhibitor's failure is about the absence of a spindle, not about access to the DNA. (Choice B) reverses and mislabels the real mechanism: bacteria do not assemble a chromosome-pulling spindle of any kind, and the FtsZ ring constricts the membrane rather than dragging chromosomes along filaments, so this answer invents a spindle that does not exist. (Choice C) confuses transient arrest with true insensitivity; the cells are not pausing and resuming a spindle-driven division, because they never used a spindle—division continues uninterrupted via FtsZ. (Choice D) is correct because binary fission uses the FtsZ constriction ring, not a microtubule spindle, leaving the drug without a target. This is a Scientific Reasoning and Problem Solving question because you must apply the binary-fission-versus-mitosis distinction to predict that a spindle-targeting drug will not affect an organism whose division mechanism does not involve a spindle.$ex54$,
    'medium', '2B', $cc54$Prokaryotes and Viruses (BIO)$cc54$, 'biology', 2, 105
  ) RETURNING id
)
