UNION ALL SELECT id, 'B', 'reversed_relationship', $a66B$Reverses the direction of dye movement — claims ethanol adds complex rather than extracting it$a66B$ FROM q
UNION ALL SELECT id, 'C', 'process_step_confusion', $a66C$Misorders the protocol — treats the counterstain as present before decolorization$a66C$ FROM q;

-- Q17 [Prokaryotic Domains: Archaea and Bacteria · easy · Skill 1 · ans B] (g56)
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES (
    'bio_biochem', 'The Cell', 'Prokaryotic Domains: Archaea and Bacteria',
    $qt56$A student sorts the three domains of life into a "prokaryotic" group and a "eukaryotic" group, placing each domain by whether its members enclose their genetic material in a true membrane-bound nucleus. One of the three domains does NOT belong in the prokaryotic group. Which domain must the student place in the eukaryotic group?$qt56$,
    $op56$[{"label":"A","text":"Archaea, because its members are extremophiles that lack a nucleoid"},{"label":"B","text":"Eukarya, because its members enclose their DNA in a membrane-bound nucleus"},{"label":"C","text":"Bacteria, because its members have a peptidoglycan cell wall surrounding the nucleus"},{"label":"D","text":"Both Bacteria and Archaea, because both enclose their DNA in a membrane-bound nucleus"}]$op56$::jsonb,
    'B',
    $ex56$This is a Biology question that falls under the content category 'Prokaryotes and Viruses (BIO)'. The answer is B because, of the three domains of life, only Eukarya contains organisms whose cells enclose their DNA within a true membrane-bound nucleus; Bacteria and Archaea are the two prokaryotic domains, and their cells lack a membrane-enclosed nucleus. Carl Woese's rRNA-based tree separated life into "three domains: Bacteria, Archaea, and Eukarya," and the text states plainly that of these, "the first two are prokaryotic cells with microbes that lack membrane-enclosed nuclei and organelles," while "the third domain contains the eukaryotes." A prokaryote keeps its DNA in a nucleoid region rather than a true nucleus, whereas eukaryotic cells partition the genome behind a nuclear envelope, which is the single defining contrast the student is sorting on. (Choice A) Archaea is incorrect: it is one of the two prokaryotic domains, so it belongs in the prokaryotic group, not the eukaryotic group; many archaea are extremophiles, but they still lack a membrane-bound nucleus and do have a nucleoid. (Choice B) is correct: Eukarya is the only domain whose members wrap their DNA in a membrane-bound nucleus, so it is the non-prokaryotic domain. (Choice C) Bacteria is incorrect: it is prokaryotic and therefore has no nucleus at all, so describing a peptidoglycan wall as surrounding "the nucleus" is doubly wrong. (Choice D) is incorrect because it reverses the relationship: Bacteria and Archaea are precisely the domains that do NOT have a membrane-bound nucleus, which is why they are classified as prokaryotic. This is a Knowledge of Scientific Concepts and Principles question because you must recall that Eukarya is the sole non-prokaryotic domain and that the defining feature is a membrane-bound nucleus.$ex56$,
    'easy', '2B', $cc56$Prokaryotes and Viruses (BIO)$cc56$, 'biology', 1, 75
  ) RETURNING id
)
INSERT INTO question_distractor_metadata (question_id, choice_label, distractor_category, archetype)
SELECT id, 'A', 'adjacent_fact', $a56A$Names a real prokaryotic domain (Archaea) and a true fact about it (extremophiles) but misassigns it to the eukaryotic group$a56A$ FROM q
UNION ALL SELECT id, 'C', 'misconception', $a56C$Treats Bacteria as eukaryotic by inventing a nucleus for it (peptidoglycan wall 'around the nucleus'), conflating cell wall with nuclear envelope$a56C$ FROM q
UNION ALL SELECT id, 'D', 'reversed_relationship', $a56D$Inverts the prokaryote/eukaryote criterion, claiming the two prokaryotic domains are the ones with a membrane-bound nucleus$a56D$ FROM q;

-- Q18 [Prokaryotic Domains: Archaea and Bacteria · medium · Skill 2 · ans C] (g57)
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES (
    'bio_biochem', 'The Cell', 'Prokaryotic Domains: Archaea and Bacteria',
    $qt57$A microbiologist adds an antibiotic that blocks peptidoglycan cross-linking to a culture containing both a rod-shaped bacterium and an acid-loving archaeal extremophile. After incubation, the bacterial cells lyse while the archaeal cells continue to divide normally. Which feature of the archaeal cells best accounts for their survival?$qt57$,
    $op57$[{"label":"A","text":"Their genetic material is enclosed within a membrane-bound nucleus, which shields the cell wall from the antibiotic"},{"label":"B","text":"Their ribosomes are 80S rather than 70S, so the antibiotic cannot disrupt their protein synthesis"},{"label":"C","text":"Their cell walls lack peptidoglycan, so the antibiotic has no peptidoglycan cross-links to block"},{"label":"D","text":"Their cell walls are built from cellulose, which the antibiotic strengthens rather than weakens"}]$op57$::jsonb,
    'C',
    $ex57$This is a Biology question that falls under the content category 'Prokaryotes and Viruses (BIO)'. The answer is C because archaeal cell walls do not contain peptidoglycan, so an antibiotic that works by blocking peptidoglycan cross-linking has no target in archaea, leaving their walls intact while the peptidoglycan-dependent bacteria lyse. The textbook states that bacteria are prokaryotic and that "Most bacteria have cell walls that contain peptidoglycan," which is exactly the structure the antibiotic disrupts. By contrast, the text notes that "Unlike most bacteria, archaeal cell walls do not contain peptidoglycan, but their cell walls are often composed of a similar substance called pseudopeptidoglycan." Because the cross-linking the drug targets is specific to true peptidoglycan, the archaea retain a load-bearing wall and resist osmotic lysis. The scenario reflects how beta-lactam-type agents that act on peptidoglycan spare archaea. (Choice A) Archaea are prokaryotic and lack a membrane-bound nucleus; the text describes Bacteria and Archaea as "prokaryotic cells with microbes that lack membrane-enclosed nuclei and organelles," so this names a structure archaea do not have. (Choice B) Prokaryotic ribosomes, including those of archaea, are 70S, not 80S, and in any case the antibiotic described acts on the cell wall rather than on ribosomes, so this is irrelevant to wall integrity. (Choice C) is correct because the absence of peptidoglycan removes the drug's molecular target, so the wall is not weakened and the cell does not lyse. (Choice D) Cellulose-based walls characterize algal protists, not archaea, whose walls are often pseudopeptidoglycan; the text contrasts the "cellulose-based cell wall of the algal protists" with prokaryotic walls, and no antibiotic strengthens a wall it acts on. This is a Scientific Reasoning and Problem Solving question because you must apply the structural difference between archaeal and bacterial cell walls to predict which organism survives a wall-targeting antibiotic.$ex57$,
    'medium', '2B', $cc57$Prokaryotes and Viruses (BIO)$cc57$, 'biology', 2, 105
  ) RETURNING id
)
INSERT INTO question_distractor_metadata (question_id, choice_label, distractor_category, archetype)
SELECT id, 'A', 'misconception', $a57A$Attributing a eukaryotic feature (membrane-bound nucleus) to prokaryotic archaea$a57A$ FROM q
UNION ALL SELECT id, 'B', 'scale_unit_error', $a57B$Swapping 70S prokaryotic ribosomes for 80S eukaryotic ribosomes and invoking the wrong drug target$a57B$ FROM q
UNION ALL SELECT id, 'D', 'adjacent_fact', $a57D$Borrowing the cellulose wall of algal protists and reversing the drug's effect$a57D$ FROM q;

-- Q19 [Prokaryotic Domains: Archaea and Bacteria · hard · Skill 2 · ans D] (g58)
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES (
    'bio_biochem', 'The Cell', 'Prokaryotic Domains: Archaea and Bacteria',
    $qt58$A researcher characterizes a newly isolated single-celled organism and confirms it has a single circular chromosome and no membrane-bound nucleus, yet its DNA is packaged with histone-like proteins and its RNA polymerase and translation-initiation machinery closely resemble those of human cells. To which domain should she assign the organism, and why is the colleague's inference that "the histones make it eukaryotic" wrong?$qt58$,
    $op58$[{"label":"A","text":"Bacteria, because a single circular chromosome with no nucleus is the defining bacterial profile, and the histone-like packaging proteins are simply this bacterium's nucleoid-associated proteins doing the same job that histones do in other cells."},{"label":"B","text":"Eukarya, because only eukaryotic cells wrap their DNA around histones; the absence of a nucleus reflects an early developmental stage rather than a true domain difference, so the colleague's inference is correct."},{"label":"C","text":"Eukarya, because the eukaryote-like RNA polymerase and translation-initiation machinery are the molecular features that truly define a domain, and these outweigh the lack of a nucleus when assigning the organism."},{"label":"D","text":"Archaea, because the absent nucleus and single circular chromosome make the cell prokaryotic, while the histone-like proteins and eukaryote-resembling transcription and translation machinery distinguish it from Bacteria; histones do not require a nucleus, so they cannot make a cell eukaryotic."}]$op58$::jsonb,
    'D',
    $ex58$This is a Biology question that falls under the content category 'Prokaryotes and Viruses (BIO)'. The answer is D because the organism is structurally prokaryotic (no nucleus, a single circular chromosome) yet carries the histone-like DNA-organizing proteins and the eukaryote-resembling transcription/translation machinery that are hallmarks of Archaea, not Bacteria. Domain assignment rests first on the nuclear criterion: "Microbes within the domains Bacteria and Archaea are all prokaryotes (their cells lack a nucleus), whereas microbes in the domain Eukarya are eukaryotes (their cells have a nucleus)." Because the cell has no nucleus, Eukarya is excluded outright regardless of how eukaryote-like its molecular parts are. Among the two prokaryotic domains, the deciding clue is that bacteria "lack histones" whereas archaea contain them, and "in archaea, the nucleoid is organized by either NAPs or histone-like DNA organizing proteins"; archaeal ribosomes and machinery are also "more similar to their eukaryotic counterparts than to those found in bacteria." Histones organize DNA in the cytoplasmic nucleoid of an archaeon just as they could in a nucleus, so their presence reflects archaeal ancestry, not a hidden eukaryotic identity. (Choice A) A single circular chromosome with no nucleus is shared by both Bacteria and Archaea, so it cannot select Bacteria; moreover, bacteria characteristically lack histones and use bacterial-type machinery, so the histone-like packaging and eukaryote-like polymerase actively point away from Bacteria. (Choice B) Histones are not exclusive to eukaryotes — archaea also possess histone-like proteins — and the absence of a nucleus is a defining, not developmental, feature, so this inference is the exact error the stem flags. (Choice C) This reverses the actual hierarchy of criteria: the presence or absence of a membrane-bound nucleus, not the resemblance of the transcription/translation machinery, is what separates the eukaryotic domain from the two prokaryotic domains; eukaryote-like machinery in a nucleus-free cell is precisely the archaeal signature. (Choice D) Correct: the absent nucleus and single circular chromosome make the cell prokaryotic, so Eukarya is excluded, while the histone-like DNA-organizing proteins and eukaryote-resembling transcription and translation machinery are the hallmarks that distinguish Archaea from Bacteria; because histones can organize DNA in a cytoplasmic nucleoid, their presence reflects archaeal ancestry rather than a eukaryotic identity. This is a Scientific Reasoning and Problem Solving question because you must integrate several structural and molecular clues, apply the nuclear criterion before the molecular one, and reject a plausible but partial-truth inference to reach the correct domain.$ex58$,
    'hard', '2B', $cc58$Prokaryotes and Viruses (BIO)$cc58$, 'biology', 2, 150
  ) RETURNING id
)
INSERT INTO question_distractor_metadata (question_id, choice_label, distractor_category, archetype)
SELECT id, 'A', 'partial_truth', $a58A$Stops at 'prokaryote = bacterium,' treating the nucleus-absent circular-chromosome profile as uniquely bacterial and explaining away the histone clue$a58A$ FROM q
UNION ALL SELECT id, 'B', 'misconception', $a58B$The explicitly-flagged 'histones are eukaryote-only, so it must be eukaryotic' trap, dismissing the missing nucleus$a58B$ FROM q
UNION ALL SELECT id, 'C', 'reversed_relationship', $a58C$Inverts the criterion hierarchy — treats eukaryote-like molecular machinery, not the nuclear membrane, as the domain-defining feature$a58C$ FROM q;

-- Q20 [Prokaryotic Flagella & Motility · medium · Skill 2 · ans A] (g67)
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES (
    'bio_biochem', 'The Cell', 'Prokaryotic Flagella & Motility',
    $qt67$A motile soil bacterium is treated with a drug that collapses the proton-motive force across its plasma membrane. The cell abruptly stops swimming, yet electron microscopy shows that its external flagellar filament and the curved segment linking that filament to the cell envelope both remain structurally intact. The component whose disabled function MOST directly accounts for the loss of motility is the:$qt67$,
    $op67$[{"label":"A","text":"basal body, the membrane-embedded rotary motor that spins the flagellum"},{"label":"B","text":"flagellin filament, the rigid helical propeller that extends into the surrounding solution"},{"label":"C","text":"hook, the flexible coupling that joins the filament to the structure anchored in the membrane"},{"label":"D","text":"axoneme, the \\(9+2\\) microtubule array whose dynein arms drive bending of the flagellum"}]$op67$::jsonb,
    'A',
    $ex67$This is a Biology question that falls under the content category 'Prokaryotes and Viruses (BIO)'. The answer is A because the basal body is the membrane-embedded rotary motor that physically spins the bacterial flagellum, and it is powered by the proton-motive force; collapsing that gradient removes the motor's energy source and freezes rotation even though every other flagellar part is intact. The text states that "Bacterial flagella act like propellers. They are stiff spiral filaments composed of flagellin protein subunits that extend outward from the cell and spin in solution. The basal body is the motor for the flagellum and is embedded in the plasma membrane," and that "A hook region connects the basal body to the filament." Because the motor sits in the plasma membrane and harnesses the proton gradient across that membrane to turn, dissipating the proton-motive force directly stops the motor while the passive filament and hook, which carry out no energy conversion of their own, stay structurally unchanged. The clue that the filament and the linking segment (the hook) are both intact rules out any structural break and points to the energized motor as the disabled element. (Choice A) is correct: the basal body is the rotary motor embedded in the plasma membrane, the only listed part that consumes the proton-motive force to generate rotation, so collapsing that force halts motility. (Choice B) is wrong because the flagellin filament is the passive propeller that is spun by the motor; it generates no force itself, and the stem explicitly states it remains intact. (Choice C) is wrong because the hook is only a flexible coupling that transmits the motor's torque from the basal body to the filament; it does not convert the proton gradient into rotation and is also described as intact. (Choice D) is wrong because the 9+2 axoneme with dynein arms is the engine of a eukaryotic flagellum, which bends rather than rotates and is driven by ATP, not the proton-motive force; bacterial flagella have no axoneme. This is a Scientific Reasoning and Problem Solving question because you must connect the energy source that was disrupted to the one flagellar component that depends on it and eliminate the parts that are merely structural or that belong to a different (eukaryotic) flagellar system.$ex67$,
    'medium', '2B', $cc67$Prokaryotes and Viruses (BIO)$cc67$, 'biology', 2, 105
  ) RETURNING id
)
INSERT INTO question_distractor_metadata (question_id, choice_label, distractor_category, archetype)
SELECT id, 'B', 'partial_truth', $a67B$Names a real flagellar part (filament) that is essential to swimming but is passively spun, not the force generator$a67B$ FROM q
UNION ALL SELECT id, 'C', 'process_step_confusion', $a67C$Confuses the torque-transmitting coupling (hook) with the torque-generating motor$a67C$ FROM q
UNION ALL SELECT id, 'D', 'adjacent_fact', $a67D$Imports the correct eukaryotic flagellar mechanism (9+2 dynein axoneme) into a prokaryote where it does not exist$a67D$ FROM q;

-- Q21 [Prokaryotic Flagella & Motility · hard · Skill 2 · ans B] (g68)
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES (
    'bio_biochem', 'The Cell', 'Prokaryotic Flagella & Motility',
    $qt68$A microbiologist watches a swimming \(E.\ coli\) cell and a human sperm cell, each driven by a single posterior flagellum, and notes that the sperm flagellum propels the cell by propagating a whip-like bend along its length. She proposes that the \(E.\ coli\) flagellum generates thrust the same way. Why CANNOT the bacterial flagellum produce propulsion by this bending mechanism?$qt68$,
    $op68$[{"label":"A","text":"The bacterial flagellum lacks a basal body, so it has no anchor against which a propagating bend could push the surrounding fluid."},{"label":"B","text":"The bacterial flagellum is a stiff flagellin filament turned as a rigid propeller by a rotary basal-body motor, not a flexible microtubule axoneme whose dynein arms slide doublets to create bends."},{"label":"C","text":"The bacterial flagellum is built from a 9+2 microtubule array like the sperm flagellum, but its dynein arms rotate the whole filament instead of sliding the doublets."},{"label":"D","text":"The bacterial flagellum bends using flagellin cross-bridges rather than dynein, so it produces a slower but mechanistically identical whip-like stroke."}]$op68$::jsonb,
    'B',
    $ex68$This is a Biology question that falls under the content category 'Prokaryotes and Viruses (BIO)'. The answer is B because the bacterial flagellum is a rigid flagellin filament spun like a propeller by a rotary basal-body motor, whereas the sperm's bending stroke depends on a flexible 9+2 microtubule axoneme in which dynein motor arms slide adjacent doublets past each other; these are mechanistically different propulsion systems and the bacterial structure has none of the parts needed to bend. The Microbiology text states that "the prokaryotic flagellum is a stiff, rotating structure," while "a eukaryotic flagellum is more like a flexible whip composed of nine parallel pairs of microtubules surrounding a central pair of microtubules... The parallel microtubules use dynein motor proteins to move relative to each other, causing the flagellum to bend" (~lines 5669-5673). Earlier the text describes bacterial flagella as "stiff spiral filaments composed of flagellin protein subunits that extend outward from the cell and spin in solution," driven by a basal body that "is the motor for the flagellum" (~lines 4922-4924). A stiff, rotating flagellin propeller therefore cannot execute the dynein-driven sliding-and-bending stroke used by the microtubule-based sperm flagellum. (Choice A) The bacterial flagellum DOES have a basal body — it is precisely the rotary motor embedded in the membrane — so claiming it lacks one is factually wrong; moreover, the real reason is the absence of a slideable microtubule axoneme, not a missing anchor. (Choice B) Correct: a stiff flagellin filament spun by a rotary motor is structurally incapable of the dynein-sliding bend, which is the textbook contrast. (Choice C) The bacterial flagellum is built of flagellin protein, NOT a 9+2 microtubule array, and it contains no dynein; this imports eukaryotic axonemal architecture onto bacteria, which the text explicitly distinguishes. (Choice D) Bacterial flagella have no dynein and do not bend at all — they rotate as rigid propellers — so the stroke is not "mechanistically identical"; this is the partial-truth trap that concedes the wrong mechanism. This is a Scientific Reasoning and Problem Solving question because you must compare two propulsion systems and infer why the structural makeup of the bacterial flagellum rules out the eukaryotic bending mechanism.$ex68$,
    'hard', '2B', $cc68$Prokaryotes and Viruses (BIO)$cc68$, 'biology', 2, 150
  ) RETURNING id
)
INSERT INTO question_distractor_metadata (question_id, choice_label, distractor_category, archetype)
SELECT id, 'A', 'misconception', $a68A$Denies a structure the bacterial flagellum actually has (the basal-body motor) and invents a wrong causal reason$a68A$ FROM q
UNION ALL SELECT id, 'C', 'process_step_confusion', $a68C$Imports the eukaryotic 9+2 dynein axoneme onto bacteria while swapping rotation for sliding$a68C$ FROM q
UNION ALL SELECT id, 'D', 'partial_truth', $a68D$Concedes a dynein-free bend but falsely calls the bacterial stroke mechanistically identical to the eukaryotic whip$a68D$ FROM q;

-- Q22 [Prokaryotic Growth & Metabolism · easy · Skill 1 · ans C] (g69)
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES (
    'bio_biochem', 'The Cell', 'Prokaryotic Growth & Metabolism',
    $qt69$A rod-shaped bacterium placed in nutrient-rich broth copies its single circular chromosome, elongates, and pinches in at its midpoint to yield two cells, each carrying one complete and identical copy of the parental genome. This reproductive event is BEST identified as:$qt69$,
    $op69$[{"label":"A","text":"mitosis, in which a duplicated set of linear chromosomes is pulled apart by a spindle into two identical nuclei"},{"label":"B","text":"budding, in which a small outgrowth swells at one pole and detaches as a smaller daughter cell"},{"label":"C","text":"binary fission, in which the replicated circular chromosome is partitioned as the cell constricts into two equal, genetically identical daughters"},{"label":"D","text":"conjugation, in which a copy of plasmid DNA is transferred through a pilus from a donor cell to a recipient cell"}]$op69$::jsonb,
    'C',
    $ex69$This is a Biology question that falls under the content category 'Prokaryotes and Viruses (BIO)'. The answer is C because binary fission is the prokaryotic mechanism in which the single circular chromosome is replicated and partitioned as the cell elongates and constricts, producing two equally sized, genetically identical daughter cells. The textbook states that in binary fission "the replication of DNA starts at a location on the circular chromosome called the origin of replication," after which "the center of the enlarged cell constricts until two daughter cells are formed, each offspring receiving a complete copy of the parental genome and a division of the cytoplasm (cytokinesis)" (openstax-microbiology.txt, lines 14545-14552). This matches the described scenario exactly: one cell, a single circular chromosome, midpoint constriction, and two identical genomes. (Choice A) Mitosis is a eukaryotic process that separates duplicated linear chromosomes using a spindle; the textbook contrasts it with prokaryotic division, noting mitosis "is a much more complex cellular process than binary fission" and that prokaryotes have a single chromosome (openstax-microbiology.txt, lines 15159-15161), so it does not describe a bacterium with one circular chromosome. (Choice B) Budding does occur in a few prokaryotes, but it is an asymmetrical division in which "the tip of the extension swells and forms a smaller cell, the bud" (openstax-microbiology.txt, lines 15028-15029) — it yields unequal-sized cells, not the two equal daughters described. (Choice C) is correct. (Choice D) Conjugation transfers a copy of DNA (often a plasmid) from a donor to a recipient through a pilus; it is a form of horizontal gene transfer, not a reproductive division that splits one cell into two. This is a Knowledge of Scientific Concepts and Principles question because you must recall that binary fission is the prokaryotic division mechanism that copies the single circular chromosome and splits one cell into two genetically identical daughters.$ex69$,
    'easy', '2B', $cc69$Prokaryotes and Viruses (BIO)$cc69$, 'biology', 1, 75
  ) RETURNING id
)
INSERT INTO question_distractor_metadata (question_id, choice_label, distractor_category, archetype)
SELECT id, 'A', 'misconception', $a69A$Applying the eukaryotic division name (mitosis) to a prokaryote that lacks a nucleus and spindle$a69A$ FROM q
UNION ALL SELECT id, 'B', 'adjacent_fact', $a69B$A real but minor prokaryotic division mode (budding) that produces unequal daughters, not equal identical ones$a69B$ FROM q
UNION ALL SELECT id, 'D', 'process_step_confusion', $a69D$Confusing a gene-transfer process (conjugation) with a reproductive cell-division process$a69D$ FROM q;

-- Q23 [Prokaryotic Growth & Metabolism · medium · Skill 2 · ans D] (g70)
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES (
    'bio_biochem', 'The Cell', 'Prokaryotic Growth & Metabolism',
    $qt70$A flask of E. coli growing by aerobic respiration on glucose is sealed and stirred until the dissolved oxygen is exhausted; no nitrate, sulfate, or other inorganic electron acceptor is added to the medium. The culture keeps consuming glucose and remains viable. Compared with the aerobic phase, what is the MOST likely consequence for the cells' ATP yield per glucose molecule once oxygen is gone?$qt70$,
    $op70$[{"label":"A","text":"It stays at roughly 38 ATP per glucose, because glycolysis alone supplies that many ATP molecules regardless of oxygen."},{"label":"B","text":"It stays near the aerobic value because the cells switch to anaerobic respiration, using a built-in electron transport chain that pumps protons just as efficiently as the oxygen-dependent one."},{"label":"C","text":"It rises above the aerobic value because fermentation regenerates NAD\\(^+\\) faster, letting glycolysis run more times and net more ATP per glucose."},{"label":"D","text":"It falls to about 2 ATP per glucose, because with no electron acceptor for an electron transport chain the cells rely on fermentation, which yields ATP only from substrate-level phosphorylation during glycolysis."}]$op70$::jsonb,
    'D',
    $ex70$This is a Biology question that falls under the content category 'Prokaryotes and Viruses (BIO)'. The answer is D because, with oxygen gone and no alternative inorganic electron acceptor supplied, E. coli cannot run an electron transport chain and must turn to fermentation, which produces ATP only by substrate-level phosphorylation during glycolysis. E. coli is a facultative anaerobe: when an appropriate final electron acceptor is available it respires because "respiration allows for much greater ATP production per glucose molecule," but when none is present "NADH must be reoxidized to NAD+ ... through a process called fermentation," and "Fermentation does not involve an electron transport system and does not directly produce any additional ATP beyond that produced during glycolysis by substrate-level phosphorylation," giving "a maximum of two ATP molecules per glucose during glycolysis" (lines 13244-13254). The aerobic phase, by contrast, reaches a theoretical maximum near 38 ATP per glucose (lines 13198-13199), so removing oxygen without an alternative acceptor collapses the yield from ~38 to ~2. (Choice A) Glycolysis by itself nets only two ATP per glucose, not 38; the figure of ~38 comes from the full respiratory pathway including oxidative phosphorylation (line 13198-13199 gives the 38 total, line 13252-13254 gives the two-ATP glycolytic yield), so this choice misattributes the whole-pathway total to glycolysis. (Choice B) Anaerobic respiration does use an electron transport chain, but it requires a non-oxygen inorganic final electron acceptor (such as nitrate), and none is supplied here; moreover even when it occurs "Smaller electrochemical gradients are generated ... so less ATP is formed through anaerobic respiration" (lines 13129-13139), so it neither happens in this setup nor matches the aerobic yield. (Choice C) Fermentation regenerates NAD+ to keep glycolysis running, but it adds no ATP beyond glycolysis itself and cannot exceed the aerobic yield; "fermentation ... produce[s] very little ATP—only two ATP molecules" (lines 13251-13254, 14155-14158), so the yield falls rather than rises. (Choice D) Correct: lacking any electron acceptor, the cells ferment and net only the ~2 ATP per glucose made by substrate-level phosphorylation in glycolysis (lines 13251-13254). This is a Scientific Reasoning and Problem Solving question because you must apply the facultative-anaerobe metabolic rules to a specific change in oxygen availability and predict the quantitative energy-yield consequence rather than recall a single fact.$ex70$,
    'medium', '2B', $cc70$Prokaryotes and Viruses (BIO)$cc70$, 'biology', 2, 110
  ) RETURNING id
)
INSERT INTO question_distractor_metadata (question_id, choice_label, distractor_category, archetype)
SELECT id, 'A', 'scale_unit_error', $a70A$Attributes the whole aerobic-pathway ATP total (~38) to glycolysis alone, ignoring that oxidative phosphorylation supplies the bulk of it$a70A$ FROM q
UNION ALL SELECT id, 'B', 'partial_truth', $a70B$Invokes anaerobic respiration (a real ETS-based pathway) as if it occurs and matches aerobic yield, ignoring that it needs an alternative inorganic acceptor not present and yields less ATP$a70B$ FROM q
UNION ALL SELECT id, 'C', 'misconception', $a70C$Treats fermentation as more ATP-productive because NAD+ is recycled faster, reversing the actual energy hierarchy$a70C$ FROM q;

-- Q24 [Prokaryotic Growth & Metabolism · medium · Skill 2 · ans A] (g71)
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES (
    'bio_biochem', 'The Cell', 'Prokaryotic Growth & Metabolism',
    $qt71$A microbiologist tracks an aerobically respiring bacterium and locates the membrane across which the cell builds the proton gradient that powers its ATP synthase. No mitochondrion is present anywhere in the cell. The gradient is found across the plasma membrane. Which feature of prokaryotic cell organization most directly accounts for this localization?$qt71$,
    $op71$[{"label":"A","text":"Lacking mitochondria, the prokaryote has no other suitable membrane, so its electron transport chain and ATP synthase reside in the plasma membrane, which sustains the proton gradient there."},{"label":"B","text":"The bacterium pumps protons across its nucleoid membrane, because the circular chromosome is enclosed by a membrane that houses the electron transport chain."},{"label":"C","text":"The proton gradient forms across the outer leaflet of the peptidoglycan cell wall, which acts as the bacterium's energy-conserving membrane in place of a mitochondrion."},{"label":"D","text":"Prokaryotes localize oxidative ATP synthesis to free 70S ribosomes in the cytoplasm, which carry the electron transport chain because there is no inner mitochondrial membrane."}]$op71$::jsonb,
    'A',
    $ex71$This is a Biology question that falls under the content category 'Prokaryotes and Viruses (BIO)'. The answer is A because, lacking mitochondria, a prokaryote must house its respiratory electron transport chain and ATP synthase in the only membrane it has that can support chemiosmosis: the plasma membrane. In eukaryotes the electron transport chain and the pH gradient that drives ATP synthase sit in the inner mitochondrial membrane (OpenStax Biology 2e: "The electron transport chain is a series of electron transporters embedded in the inner mitochondrial membrane"; "the pH gradient formed by the electron transport chain is used by ATP synthase to form ATP"). Prokaryotic cells "lack a nucleus surrounded by a complex nuclear membrane" and have no membrane-bound organelles, but every prokaryote does possess a plasma membrane, so the chain and the gradient are established there instead (OpenStax Microbiology: all prokaryotes have "a cell membrane"; the photosynthetic counterparts are merely "an infolding of the plasma membrane"). (Choice A) is correct: with no mitochondrial inner membrane available, the plasma membrane is the cell's energy-conserving membrane, so the electron transport chain pumps protons across it and ATP synthase uses that gradient. (Choice B) is wrong because the nucleoid is not membrane-bound — prokaryotic DNA sits free "in the cell's central part: the nucleoid," with no enclosing membrane to host an electron transport chain. (Choice C) confuses the rigid peptidoglycan cell wall with an energy-transducing membrane; the wall "helps the cell maintain its shape" and prevents lysis, but it is not a phospholipid bilayer and cannot hold a proton-motive force. (Choice D) misplaces oxidative phosphorylation on ribosomes; 70S ribosomes synthesize proteins and have no role in electron transport or maintaining a proton gradient. This is a Scientific Reasoning and Problem Solving question because you must reason from the absence of a mitochondrion to infer which remaining structure can host chemiosmotic ATP synthesis in a prokaryote.$ex71$,
    'medium', '2B', $cc71$Prokaryotes and Viruses (BIO)$cc71$, 'biology', 2, 105
  ) RETURNING id
)
INSERT INTO question_distractor_metadata (question_id, choice_label, distractor_category, archetype)
SELECT id, 'B', 'misconception', $a71B$Treats the nucleoid as a membrane-bound compartment that could host the electron transport chain$a71B$ FROM q
UNION ALL SELECT id, 'C', 'adjacent_fact', $a71C$Substitutes the structural peptidoglycan cell wall for the energy-conserving plasma membrane$a71C$ FROM q
UNION ALL SELECT id, 'D', 'process_step_confusion', $a71D$Assigns oxidative phosphorylation to ribosomes, conflating protein synthesis machinery with the respiratory membrane$a71D$ FROM q;

-- Q25 [Prokaryotic Growth & Metabolism · hard · Skill 2 · ans B] (g72)
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES (
    'bio_biochem', 'The Cell', 'Prokaryotic Growth & Metabolism',
    $qt72$Four species are stab-inoculated into separate thioglycolate tubes in which dissolved \( \text{O}_2 \) is high near the surface and absent at the bottom. After incubation, species 2 grows only as a dense band at the very bottom and dies when a fresh culture of it is streaked onto an agar plate left open to room air, whereas species 1 grows only near the surface, species 3 grows throughout but most heavily near the top, and species 4 grows evenly throughout the tube. Which prediction about species 2 is best supported?$qt72$,
    $op72$[{"label":"A","text":"It is an aerotolerant anaerobe that bands at the bottom because it prefers anoxic conditions, yet it survives in open air because it carries superoxide dismutase to neutralize reactive oxygen species."},{"label":"B","text":"It is an obligate anaerobe that bands at the bottom because oxygen is excluded there, and it dies in open air because it lacks the enzymes that detoxify the reactive oxygen species formed from atmospheric \\( \\text{O}_2 \\)."},{"label":"C","text":"It is a facultative anaerobe that bands at the bottom because it switches to fermentation in anoxia, and it dies in open air only because the plate dries out before it can begin aerobic respiration."},{"label":"D","text":"It is an obligate anaerobe that bands at the bottom because oxygen molecules are directly too large to diffuse into its cytoplasm, sparing it from the reactive oxygen species that kill aerotolerant species."}]$op72$::jsonb,
    'B',
    $ex72$This is a Biology question that falls under the content category 'Prokaryotes and Viruses (BIO)'. The answer is B because a species that grows only at the anoxic bottom of the tube and is killed by exposure to air fits the obligate anaerobe pattern, and obligate anaerobes die in air because they lack the enzymes that detoxify reactive oxygen species. The text describes that in a thioglycolate tube, bacteria growing "at the bottom" are "obligate anaerobes, which are killed by oxygen," in contrast to facultative anaerobes that show "heavy growth at the top ... and growth throughout" and aerotolerant anaerobes that are "indifferent to the presence of oxygen" and grow throughout (lines 15249-15255). The lethality of air is mechanistic: "Obligate anaerobes usually lack all three enzymes" — superoxide dismutase, peroxidase, and catalase — while "Aerotolerant anaerobes do have SOD but no catalase" (lines 15370-15386), so an obligate anaerobe cannot neutralize the reactive oxygen species that "can damage virtually any macromolecule or structure with which they come in contact" (lines 15214-15215). Species 1 (surface only) is the obligate aerobe, species 3 (throughout, heaviest at top) is the facultative anaerobe, and species 4 (even throughout) is the aerotolerant anaerobe, leaving the bottom-banding, air-killed species 2 as the obligate anaerobe. (Choice A) is a partial-truth trap: aerotolerant anaerobes do carry SOD and survive air, but they grow evenly throughout the tube (that is species 4), not as a bottom-only band, and air-survival contradicts species 2's death in open air. (Choice B) is correct: bottom banding plus death in air identifies an obligate anaerobe, and the killing mechanism is the absence of the ROS-detoxifying enzymes. (Choice C) is wrong because a facultative anaerobe grows throughout with heaviest growth at the top (species 3) and is not killed by air; attributing the death to plate drying ignores the enzyme deficiency that actually causes oxygen toxicity. (Choice D) reverses and garbles the mechanism: oxygen is a small molecule that readily diffuses across membranes, so exclusion by size is false, and the obligate anaerobe is the species that lacks ROS protection, not the one spared from it. This is a Scientific Reasoning and Problem Solving question because you must match each species' observed growth band to an oxygen class and then predict the molecular reason the bottom-banding species cannot survive air.$ex72$,
    'hard', '2B', $cc72$Prokaryotes and Viruses (BIO)$cc72$, 'biology', 2, 150
  ) RETURNING id
)
INSERT INTO question_distractor_metadata (question_id, choice_label, distractor_category, archetype)
SELECT id, 'A', 'partial_truth', $a72A$Aerotolerant-anaerobe conflation: correctly notes SOD confers air survival but mis-assigns the bottom-only band and ignores that the species dies in air$a72A$ FROM q
UNION ALL SELECT id, 'C', 'misconception', $a72C$Facultative-anaerobe substitution with off-mechanism death (plate drying) instead of enzyme deficiency$a72C$ FROM q
UNION ALL SELECT id, 'D', 'reversed_relationship', $a72D$Oxygen-toxicity mechanism reversed: claims O2 is excluded by molecular size and that the obligate anaerobe is spared from ROS rather than killed by it$a72D$ FROM q;

